55: // Mirrors backend StraightLineDepreciationCalculator / DecliningBalanceDepreciationCalculator /
56: // UnitsOfProductionDepreciationCalculator (ERP.Services/Implement/Accounting) so the preview matches
57: // what the actual run will post. For UnitsOfProduction, actual output isn't known ahead of time (it's
58: // entered manually per period at run time) — the preview assumes an even split of the estimated total
59: // output across the useful life, purely illustrative.
60: function buildPreviewSchedule(
61:   method: EDepreciationMethod,
62:   purchaseCost: number,
63:   salvagePercent: number,
64:   usefulLifeMonths: number,
65:   estimatedTotalOutput: number | null | undefined,
66: ): PreviewRow[] {
67:   if (!purchaseCost || !usefulLifeMonths || usefulLifeMonths <= 0) return [];
68:   if (method === EDepreciationMethod.UnitsOfProduction && !(estimatedTotalOutput! > 0)) return [];
69: 
70:   const salvageValue = Math.round((purchaseCost * salvagePercent) / 100);
71:   const depreciableBase = purchaseCost - salvageValue;
72:   const usefulLifeYears = usefulLifeMonths / 12;
73:   const factor = usefulLifeYears <= 4 ? 1.5 : usefulLifeYears <= 6 ? 2.0 : 2.5;
74:   const evenOutputPerPeriod = (estimatedTotalOutput ?? 0) / usefulLifeMonths;
75:   const outputRate = estimatedTotalOutput ? depreciableBase / estimatedTotalOutput : 0;
76: 
77:   const rows: PreviewRow[] = [];
78:   let accumulated = 0;
79:   for (let period = 1; period <= usefulLifeMonths; period++) {
80:     const remaining = depreciableBase - accumulated;
81:     if (remaining <= 0) break;
82: 
83:     let amount: number;
84:     if (method === EDepreciationMethod.StraightLine) {
85:       const straightLineAmount = depreciableBase / usefulLifeMonths;
86:       amount = remaining < straightLineAmount ? remaining : straightLineAmount;
87:     } else if (method === EDepreciationMethod.UnitsOfProduction) {
88:       amount = outputRate * evenOutputPerPeriod;
89:       amount = amount > remaining ? remaining : amount;
90:     } else {
91:       const remainingMonths = usefulLifeMonths - (period - 1);
92:       if (remainingMonths <= 0) {
93:         amount = remaining;
94:       } else {
95:         const decliningMonthly = (remaining * (factor / usefulLifeYears)) / 12;
96:         const straightLineOnRemaining = remaining / remainingMonths;
97:         amount =
98:           decliningMonthly <= straightLineOnRemaining ? straightLineOnRemaining : decliningMonthly;
99:         amount = amount > remaining ? remaining : amount;
100:       }
101:     }
102: 
103:     accumulated += amount;
104:     rows.push({ period, amount, accumulated, bookValue: purchaseCost - accumulated });
105:   }
106:   return rows;
107: }
