27:     {
28:         var locks = await Repo.Query()
29:             .OrderByDescending(x => x.EffectiveDateSnapshot)
30:             .Select(x => new AccountingPeriodLockDto
31:             {
32:                 Id = x.Id,
33:                 PeriodId = x.PeriodId,
34:                 PeriodCodeSnapshot = x.PeriodCodeSnapshot,
35:                 PeriodNameSnapshot = x.PeriodNameSnapshot,
36:                 EffectiveDateSnapshot = x.EffectiveDateSnapshot,
37:                 ExpirationDateSnapshot = x.ExpirationDateSnapshot,
38:                 LockedAt = x.LockedAt,
39:                 LockedByUser = x.CreatedByUser
40:             })
