44:     }
45: 
46:     // Deterministic across processes/.NET versions (unlike Guid.GetHashCode()) — required since the
47:     // same period must hash to the same advisory-lock key on every call, from any request.
48:     private static long ToAdvisoryLockKey(Guid id) => BitConverter.ToInt64(id.ToByteArray(), 0);
49: 
50:     public async Task<Result> LockAsync(LockPeriodRequestDto dto)
51:     {
52:         // A lock without an end date would block posting from its start date forever
53:         // (including today and the future) — almost certainly not what the operator wants.
54:         if (dto.ExpirationDateSnapshot is null)
55:             return Result.Failure(
56:                 "Kỳ này chưa có ngày kết thúc nên không thể khóa (khóa sẽ chặn mọi ghi sổ từ ngày bắt đầu kỳ trở đi, kể cả hiện tại).");
57: 
58:         Result result = Result.Success();
59: 
60:         // Serialize concurrent lock requests for the same period: without this, two requests can
61:         // both pass the ExistsAsync check before either commits, both run ClosePeriodCostingAsync
62:         // (its side effects would then run twice), and only one insert would be caught by the
63:         // unique index — the other fails with a raw DbUpdateException instead of a clean message.
64:         await _unitOfWork.ExecuteInTransactionAsync(async () =>
65:         {
66:             await _unitOfWork.AcquireAdvisoryLockAsync(ToAdvisoryLockKey(dto.PeriodId));
67: 
68:             var alreadyLocked = await Repo.ExistsAsync(x => x.PeriodId == dto.PeriodId);
69:             if (alreadyLocked)
70:             {
71:                 result = Result.Failure("Kỳ này đã được khóa.");
72:                 return;
73:             }
74: 
75:             // Freeze bình quân gia quyền cuối kỳ for warehouses using that costing method before the
76:             // lock takes effect — once locked, no posting inside this range can change the ledger rows
77:             // ClosePeriodCostingAsync reads from.
78:             var closingResult = await _closingCostService.ClosePeriodCostingAsync(
79:                 dto.PeriodId, dto.PeriodCodeSnapshot, dto.EffectiveDateSnapshot, dto.ExpirationDateSnapshot.Value);
80:             if (!closingResult.IsSuccess)
81:             {
82:                 result = Result.Failure(closingResult.Message);
83:                 return;
84:             }
85: 
86:             var entity = new AccountingPeriodLock
87:             {
88:                 PeriodId = dto.PeriodId,
89:                 PeriodCodeSnapshot = dto.PeriodCodeSnapshot,
90:                 PeriodNameSnapshot = dto.PeriodNameSnapshot,
91:                 EffectiveDateSnapshot = dto.EffectiveDateSnapshot,
92:                 ExpirationDateSnapshot = dto.ExpirationDateSnapshot,
93:                 LockedAt = DateTimeOffset.UtcNow,
94:                 CreatedByUser = _currentUserService.Username
95:             };
96: 
97:             await Repo.AddAsync(entity);
98:             await _unitOfWork.SaveChangesAsync();
99: 
100:             result = Result.Success(message: $"Đã khóa kỳ {dto.PeriodCodeSnapshot}.");
101:         });
102: 
103:         return result;
104:     }
105: 
106:     public async Task<Result> UnlockAsync(Guid periodId)
107:     {
108:         Result result = Result.Success();
109: 
110:         // Mirrors LockAsync: the lock row and the frozen period costing are one unit. Dropping only the
111:         // lock would leave InventoryPeriodClosingCost behind, which keeps valuation frozen as if the
112:         // period were still closed AND makes a later re-lock fail on ClosePeriodCostingAsync's
113:         // "đã được chốt giá bình quân cuối kỳ" guard — the period could never be locked again.
114:         try
115:         {
116:             await _unitOfWork.ExecuteInTransactionAsync(async () =>
117:             {
118:                 await _unitOfWork.AcquireAdvisoryLockAsync(ToAdvisoryLockKey(periodId));
119: 
120:                 var entity = await Repo.Query().FirstOrDefaultAsync(x => x.PeriodId == periodId);
121:                 if (entity is null)
122:                 {
123:                     result = Result.Failure("Kỳ này chưa được khóa.");
124:                     return;
125:                 }
126: 
127:                 await Repo.DeleteRangeAsync([entity]);
128:                 await _unitOfWork.SaveChangesAsync();
129: 
130:                 var reopenResult = await _closingCostService.ReopenPeriodCostingAsync(periodId);
131:                 if (!reopenResult.IsSuccess)
132:                     // Roll the whole unlock back — the lock row must not disappear while the frozen
133:                     // costing it belongs to stays behind.
134:                     throw new InvalidOperationException(reopenResult.Message);
135: 
136:                 result = Result.Success(message: $"Đã mở khóa kỳ {entity.PeriodCodeSnapshot}.");
137:             });
138:         }
139:         catch (InvalidOperationException ex)
140:         {
141:             return Result.Failure(ex.Message);
142:         }
143: 
144:         return result;
145:     }
